\end{tabular}%
}
\begin{flushleft}
\footnotesize $^{\dagger}$ At $\alpha = +20$, the control flip rate exceeds steering ($p = 0.053$), indicating coherence collapse at extreme perturbation magnitudes.
\end{flushleft}
\end{table}
